<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';send_cors_headers();$principal=require_principal(['influencer']);$id=$principal['id'];$db=get_db();$campaigns=$db->prepare('SELECT c.*,l.id AS link_id,l.code,l.destination_url,l.status AS link_status FROM influencer_referral_links l JOIN influencer_campaigns c ON c.id=l.campaign_id WHERE l.influencer_id=:id ORDER BY c.ends_at DESC');$campaigns->execute(['id'=>$id]);$stats=$db->prepare('SELECT COUNT(*) conversions,COALESCE(SUM(order_amount),0) revenue,COALESCE(SUM(commission_amount),0) commission FROM influencer_conversions WHERE influencer_id=:id');$stats->execute(['id'=>$id]);$clicks=$db->prepare('SELECT COUNT(*) FROM referral_clicks c JOIN influencer_referral_links l ON l.id=c.referral_link_id WHERE l.influencer_id=:id');$clicks->execute(['id'=>$id]);$balance=$db->prepare('SELECT status,COALESCE(SUM(amount),0) amount FROM influencer_ledger_entries WHERE influencer_id=:id GROUP BY status');$balance->execute(['id'=>$id]);json_response(200,['success'=>true,'campaigns'=>$campaigns->fetchAll(),'stats'=>$stats->fetch()+['clicks'=>(int)$clicks->fetchColumn()],'balances'=>$balance->fetchAll()]);
